"use client";

import { type HTMLAttributes, type KeyboardEvent, type PointerEvent, useCallback, useRef, useState } from "react";
import { clamp } from "../utils/motion";
import { cx, flag } from "../utils/cx";

export type SliderProps<V extends number | [number, number] = number> = Omit<
  HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> & {
  /** Names the slider for assistive tech (required: a slider has no visible text of its own). */
  "aria-label": string;
  min?: number;
  max?: number;
  /** Granularity. The thumb glides between steps rather than jumping. Default 1. */
  step?: number;
  /** A number for one thumb, or `[low, high]` for a range. */
  value?: V;
  defaultValue?: V;
  onValueChange?: (value: V) => void;
  /** Called when a drag or key press ends, for saving. */
  onValueCommit?: (value: V) => void;
  disabled?: boolean;
  /** Show the current value (or range) beside the track. */
  showValue?: boolean;
  /** Format the shown value and `aria-valuetext`. */
  formatValue?: (value: number) => string;
  /** Form field name (a hidden input per thumb: `name` or `name[]` for a range). */
  name?: string;
};

const decimals = (n: number) => (String(n).split(".")[1] ?? "").length;

/**
 * A custom slider: pointer, touch and keyboard (arrows, Page keys, Home, End), one thumb or a range. The visual
 * position glides between values with a short eased transition, so dragging and key presses never jump. Each thumb is
 * `role="slider"` with `aria-valuenow/min/max`.
 */
export function Slider<V extends number | [number, number] = number>({
  min = 0,
  max = 100,
  step = 1,
  value: controlled,
  defaultValue,
  onValueChange,
  onValueCommit,
  disabled,
  showValue,
  formatValue = (v) => String(v),
  name,
  className,
  style,
  ...rest
}: SliderProps<V>) {
  const isRange = Array.isArray(controlled ?? defaultValue);
  const [inner, setInner] = useState<number[]>(() => {
    const d = defaultValue ?? min;
    return Array.isArray(d) ? [...d] : [d];
  });
  const values = controlled === undefined ? inner : Array.isArray(controlled) ? controlled : [controlled];
  const track = useRef<HTMLDivElement>(null);
  const active = useRef(0);
  const [dragging, setDragging] = useState(false);
  const places = Math.max(decimals(step), decimals(min));

  const snap = useCallback(
    (v: number) => {
      const s = Math.round((v - min) / step) * step + min;
      return Number(clamp(s, min, max).toFixed(places));
    },
    [min, max, step, places],
  );
  const emit = (next: number[], commit = false) => {
    if (controlled === undefined) setInner(next);
    const out = (isRange ? [next[0], next[1]] : next[0]) as V;
    onValueChange?.(out);
    if (commit) onValueCommit?.(out);
  };
  const setThumb = (i: number, v: number, commit = false) => {
    const next = [...values];
    const lo = i > 0 ? (next[i - 1] ?? min) : min;
    const hi = i < next.length - 1 ? (next[i + 1] ?? max) : max;
    next[i] = clamp(snap(v), lo, hi);
    if (next[i] !== values[i] || commit) emit(next, commit);
  };
  const fromPointer = (e: PointerEvent) => {
    const r = track.current?.getBoundingClientRect();
    if (!r || !r.width) return min;
    return min + clamp((e.clientX - r.left) / r.width, 0, 1) * (max - min);
  };

  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (disabled || e.button !== 0) return;
    const v = fromPointer(e);
    // the nearest thumb moves (the last one wins a tie at the high end)
    let nearest = 0;
    values.forEach((t, i) => {
      if (Math.abs(t - v) <= Math.abs((values[nearest] ?? 0) - v)) nearest = i;
    });
    active.current = nearest;
    e.currentTarget.setPointerCapture(e.pointerId);
    setDragging(true);
    setThumb(nearest, v);
    track.current?.parentElement
      ?.querySelectorAll<HTMLElement>('[role="slider"]')
      [nearest]?.focus({ preventScroll: true });
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    if (dragging) setThumb(active.current, fromPointer(e));
  };
  const endDrag = (e: PointerEvent<HTMLDivElement>) => {
    if (!dragging) return;
    setDragging(false);
    setThumb(active.current, fromPointer(e), true);
  };
  const onKey = (i: number) => (e: KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return;
    const cur = values[i] ?? min;
    const big = step * 10;
    const to =
      e.key === "ArrowRight" || e.key === "ArrowUp"
        ? cur + step
        : e.key === "ArrowLeft" || e.key === "ArrowDown"
          ? cur - step
          : e.key === "PageUp"
            ? cur + big
            : e.key === "PageDown"
              ? cur - big
              : e.key === "Home"
                ? min
                : e.key === "End"
                  ? max
                  : null;
    if (to === null) return;
    e.preventDefault();
    setThumb(i, to, true);
  };

  const pct = (v: number) => (max === min ? 0 : ((v - min) / (max - min)) * 100);
  const lo = isRange ? pct(values[0] ?? min) : 0;
  const hi = pct(values[isRange ? 1 : 0] ?? min);
  return (
    <div
      {...rest}
      className={cx("hm-slider", className)}
      style={{ ...style, "--_lo": `${lo}%`, "--_hi": `${hi}%` } as React.CSSProperties}
      data-disabled={flag(disabled)}
      data-dragging={flag(dragging)}
    >
      <div
        ref={track}
        className="hm-slider-track"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
      >
        <span className="hm-slider-rail" />
        <span className="hm-slider-fill" />
        {values.map((v, i) => (
          <span
            key={i}
            className="hm-slider-thumb"
            style={{ "--_at": `${pct(v)}%` } as React.CSSProperties}
            role="slider"
            tabIndex={disabled ? -1 : 0}
            aria-valuemin={min}
            aria-valuemax={max}
            aria-valuenow={v}
            aria-valuetext={formatValue(v)}
            aria-disabled={disabled || undefined}
            aria-label={isRange ? `${rest["aria-label"]} ${i === 0 ? "minimum" : "maximum"}` : rest["aria-label"]}
            onKeyDown={onKey(i)}
          />
        ))}
      </div>
      {showValue ? <output className="hm-slider-value">{values.map((v) => formatValue(v)).join(" – ")}</output> : null}
      {name
        ? values.map((v, i) => <input key={i} type="hidden" name={isRange ? `${name}[]` : name} value={v} />)
        : null}
    </div>
  );
}
